			frm.add_custom_button(__("Draft Credit Note"), () => {
				frappe.call({ method: "arinox_buyer_claim_make_credit_note",
					args: { claim: frm.doc.name }, freeze: true, callback: () => frm.reload_doc() });
			});
		}
	},
});

