			frm.add_custom_button(__("Colours from Production Card"), () => load_colours(frm), __("Tools"));
		}
		if (frm.doc.status === "Approved" || frm.doc.status === "Approved with Comments") frm.dashboard.add_indicator(__(frm.doc.status), "green");
